SELECT stddev(icustays.los) AS standard_deviation FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND patients.anchor_year = 57 AND (patients.anchor_year_group BETWEEN 52 AND 62) AND (SELECT COUNT(*) FROM prescriptions WHERE prescriptions.subject_id = patients.subject_id AND prescriptions.drug_type = 'anticoagulant') > 0;